  ('bew-meat-grinder-tank', 'Lightning Cannon Gun Positions (3)', 100, 'Each.', 6),
  ('bew-meat-grinder-tank', 'Main Body', 560, 'Depleted, the vehicle shuts down and is useless.', 7),
  ('bew-carnage-tank', 'Demonic Maw', 350, NULL, 1),
  ('bew-carnage-tank', 'Headlights/Eyes (4)', 10, 'Each. Small target: Called Shot only, at -3 to strike.', 2),
