  ('bew-carnage-tank', 'Treads (4)', 200, 'Each. One lost halves speed, -25% to piloting; both lost stop it.', 4),
  ('bew-carnage-tank', 'Rear Hatch', 200, NULL, 5),
  ('bew-carnage-tank', 'Top Hatch (2)', 150, 'Each.', 6),
  ('bew-carnage-tank', 'Cannon (1)', 150, NULL, 7),
  ('bew-carnage-tank', 'Turret (top)', 300, NULL, 8),
  ('bew-carnage-tank', 'Mini-Missile Launchers (2)', 50, 'Each. Small target: Called Shot only, at -3 to strike.', 9),
