INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('bew-chaos-trooper-armor', 1, 'Lightning Forearm Gun', '1D4x10 M.D. per blast', 1, '1,200 feet (366 m)', 'Six blasts a melee round; each is one attack', '50 blasts from its own blood tank; refill from a Blood Pool or let it drain the wearer, eight blasts for 20 S.D.C., 5 H.P. or 20 M.D.C. (M.D.C. for a supernatural being)', NULL, 'Assault and ranged combat, secondarily defense. A retractable vambrace on the right forearm, modelled on a Three Galaxies weapon; the text also calls it the Lightning Cannon. Extended it looks like a lightning rod and can parry melee weapons.'),
  ('bew-chaos-trooper-armor', 2, 'Mini-Missile Launchers (3)', 'By missile; usually 1D4x10 M.D. (high explosive) or 1D6x10 M.D. (plasma)', 1, 'One mile (1.6 km)', 'One or two at a time', '6 in all', NULL, 'Anti-aircraft and anti-power armor, secondarily defense. Two sit over the shoulders and one on the left forearm.'),
  ('bew-chaos-trooper-armor', 3, 'Handheld Weapons (optional)', NULL, 0, NULL, NULL, NULL, NULL, 'One melee weapon or one gun may be carried in the hand when the Lightning Forearm Gun is not in use.'),
  ('bew-chaos-trooper-armor', 4, 'Hand to Hand Combat', NULL, 0, NULL, NULL, NULL, NULL, 'By the wearer''s own Supernatural Strength, natural abilities, magic and psionics.'),
  ('bew-meat-grinder-tank', 1, 'Meat Grinder Rolling Pins', 'Run over (01-50%): 2D6x10 M.D. to armor and 1D6x10 direct to H.P.; caught in the grinder (51-00%): 4D6x10 M.D. to armor and 2D6x10 direct to H.P.', 1, NULL, NULL, NULL, NULL, 'Fuel collection, secondarily anti-personnel. Hits anyone in front who fails to dodge, and may break bones or tear off limbs.'),
  ('bew-meat-grinder-tank', 2, 'Lightning Cannons (3)', '1D6x10 M.D. per blast', 1, '2,000 feet (610 m)', 'Four blasts per cannon a melee round; each is one attack', '50 blasts each from its own blood tank; refill from a Blood Pool or let it drain the gunner, four blasts for 20 S.D.C., 5 H.P. or 20 M.D.C. (M.D.C. for a supernatural being)', NULL, 'Assault and ranged combat, secondarily defense. One turret per gun position, 180 degrees of traverse and 45 degrees of elevation either way, each needing its own gunner; killing the gunner silences it until another takes over.'),
  ('bew-meat-grinder-tank', 3, 'Troops and Other Notes', NULL, 0, NULL, NULL, NULL, NULL, 'Troops riding in the open cargo bay can shoot over the sides or jump out to fight.'),
  ('bew-carnage-tank', 1, 'Soul Cannon', '2D6x10+10 M.D. per shot', 1, '4,000 feet (1,219 m)', 'Each shot is one of the gunner''s melee attacks', 'Two life essences a shot; holds 12 souls, six shots, and more can be brought in Soul Crystals', NULL, 'Anti-fortification, secondarily anti-tank and anti-armor. The main gun, fired from the turret by a gunner using magical sensors.'),
  ('bew-carnage-tank', 2, 'Mini-Missile Launchers (2)', 'By missile; usually 1D4x10 M.D. (high explosive) or 1D6x10 M.D. (plasma), any type possible', 1, 'Usually one mile (1.6 km)', 'Singly, or volleys of 2, 4, 6 or 8', '96 in all, 48 a launcher', NULL, 'Anti-aircraft, anti-missile and assault, secondarily defense. Horned head-shaped launchers either side of the turret, run by the gunner.'),
  ('bew-carnage-tank', 3, 'Maw Attack', '6D6 M.D. a bite, then 2D6 M.D. each melee a victim stays held', 1, 'Hand to hand', 'Three bites a melee on its own; the pilot''s hand to hand attacks when he guides it', NULL, NULL, 'Assault and anti-supernatural, secondarily anti-troop and fuel collection. Opens wide enough for a 10 ft (3 m) target and bites friend or foe alike, holding on like an alligator. A dodge of 14 or better escapes as the jaws close or reopen. Blood goes to the Blood Pool; a Soulmancer aboard or nearby can tear out the life essences of victims for the Soul Cannon or his Soul Crystals.'),
  ('bew-carnage-tank', 4, 'Chain Launchers (4)', '1D6 M.D. as a blunt strike; 3D6 M.D. clawing or grabbing, with a 01-33% chance to snare and haul the target toward the maw', 1, '200 feet (61 m)', 'Once a melee; reels in 100 ft (30.5 m) a melee', 'One reusable chain per launcher', '-2 to strike', 'Climbing Hell Pits, secondarily fuel collection. Clawed grapples at the four corners that anchor the tank, haul it up sheer walls and over pit edges, and can snare demons, power armor and light vehicles.'),
  ('bew-carnage-tank', 5, 'Ram Attack', '2D6 M.D. up to 45 mph (72 km), 4D6 M.D. above; +3D6 M.D. to anyone run over', 1, NULL, NULL, NULL, NULL, 'Bashing through fences, walls and fortifications and running down infantry.'),
  ('bew-walking-death', 1, 'Head', 'Fire breath 1D4x10 M.D. to the target and all within 10 ft (3 m); head-butt or swat 4D6 M.D.; bite 2D6 M.D. restrained, 6D6+6 M.D. at full strength', 1, '300 feet (91.4 m) for the fire breath; melee for the rest', 'Up to four fire blasts a melee round', 'Unlimited, drawn from the Blood Pillar', NULL, 'Anti-personnel and assault, secondarily defense. Directed by the pilot. In a bunker, cave or unsealed vehicle, anyone caught by the flames without air or environmental gear must save vs poison or pass out for 1D4 melee rounds. Victims'' blood is pumped to the Blood Pool, so pilots chew and hold prey to drain it.'),
  ('bew-walking-death', 2, 'Lightning Cannons (4)', '1D6x10 M.D. per blast', 1, '2,000 feet (610 m)', 'Four blasts per cannon a melee round; each is one of its gunner''s attacks', '50 blasts each from its own blood tank; refill from a Blood Pool or let it drain the gunner, four blasts for 20 S.D.C., 5 H.P. or 20 M.D.C. (M.D.C. for a supernatural being); one sacrificed soul refills all four with 50 each', NULL, 'Assault and ranged combat, secondarily defense. Mounted two a side on the Combat Saddle, 180 degrees of traverse and 45 degrees of elevation either way, manned by gunners or other riders. Surplus mass-production guns, not tied to the robot''s own power.'),
  ('bew-walking-death', 3, 'Mini-Missile Launchers (2)', 'By missile; usually 1D4x10 M.D. (high explosive) or 1D6x10 M.D. (plasma), any type possible', 1, 'One mile (1.6 km)', 'Singly, or volleys of 2, 4 or 8', '32 in all, 16 a launcher', NULL, 'Anti-aircraft and anti-missile, secondarily assault and defense. Built into the Combat Saddle; the gunner or second rider fires them, the pilot at need.'),
  ('bew-walking-death', 4, 'The Tail', '2D6 M.D. light swat; 4D6 M.D. full-strength strike; sweep 2D6 M.D. to each who fails to dodge; brush away 1 M.D.', 1, '100 feet (30.5 m)', NULL, NULL, NULL, 'Anti-personnel and defense, secondarily assault; the pilot controls it. Sweep (one attack): to one side or the rear, never the front; one or two foes up to 30 ft (9.1 m) tall or dozens 10 ft (3 m) or under dodge at -2 or lose initiative and two attacks, and are then -3 to dodge stomps or fire. Brush away (two attacks): foes under 10 ft (3 m) and up to 1,000 lbs (450 kg) dodge at -2 or are flung 2D6+40 ft (12.8-15.8 m) and lose initiative and 1D4 attacks.'),
  ('bew-walking-death', 5, 'Spell Casting Abilities and Special Magic Capabilities', NULL, 0, NULL, NULL, NULL, NULL, 'Eight casts per 24 hours at 8th level potency; a Soulmancer riding or within 20 ft (6.1 m) can pay his own P.P.E. (the spell''s normal cost) for more. Accelerated Decay (Necromancy; three times a day): stores and crops within 1,000 ft (305 m) rot as with Spoil after an hour. Animate and Control Dead: the dead within 50 ft (15.2 m) rise and guard it at the commander''s orders, given by voice or the saddle''s loudspeaker. Grip of Death (Necromancy, modified): skeletal hands grow from its own hide to seize climbers. Stench of the Dead (Necromancy): always on; anyone entering must save at 13 or more, 8th level effect.'),
  ('bew-walking-death', 6, 'Hand to Hand Combat', '4D6 M.D. stomp; 1D6x10 M.D. power stomp (two attacks); 2D6 M.D. body bump; 1D6x10 M.D. ram (two attacks); no kicks', 1, NULL, NULL, NULL, NULL, 'Supernatural Strength; attacks equal its commanding rider''s +3. Head and tail attacks are listed separately.'),
  ('bew-walking-death', 7, 'Riders Can Join Combat', NULL, 0, NULL, NULL, NULL, NULL, 'Usually two or more riders, one or two if 15 ft (4.6 m) or larger, three medium-sized (pilot and two gunners), 1-6 human-sized (pilot, two gunners, 1-3 passengers). Any may shoot from its back or dismount to fight, and escorts often travel with it.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 machines are in' AS assertion, count(*) AS got, 4 AS want
  FROM vehicles WHERE slug IN ('bew-chaos-trooper-armor', 'bew-meat-grinder-tank', 'bew-carnage-tank', 'bew-walking-death');
SELECT 'their 36 locations are in' AS assertion, count(*) AS got, 36 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('bew-chaos-trooper-armor', 'bew-meat-grinder-tank', 'bew-carnage-tank', 'bew-walking-death');
SELECT 'their 19 weapon entries are in' AS assertion, count(*) AS got, 19 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('bew-chaos-trooper-armor', 'bew-meat-grinder-tank', 'bew-carnage-tank', 'bew-walking-death');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('bew-chaos-trooper-armor', 'bew-meat-grinder-tank', 'bew-carnage-tank', 'bew-walking-death') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

